var pi = PhaseManager.get_current_phase_instance()
var d = AIPlayer.request_suggestion()
var types = []
for r in d.get("_ai_decision_records", []):
	types.append(str(r.get("decision_type", "")))
if "new_orders" in types:
	return "STOP " + str(types)
var r2 = pi.execute_action(d)
return str(types) + " " + str(d.get("_ai_description", "")) + " -> " + str(r2.get("success", false))

